// The manifest's generated files, as text: plain data in, file contents out.
// scripts/generate-protocol.ts writes them; test/protocol-generate.test.ts
// checks that the checked-in copies are current.
import type { DevLinkProtocol } from './dev-link.ts';
import {
  cppLayouts,
  eventLayouts,
  kernelLayouts,
  kotlinLayouts,
  swiftLayouts,
} from './event-layouts.ts';
import type { ErrorSpec, ModuleProtocol } from './modules.ts';
import {
  cppSchemas,
  flattenValue,
  kotlinSchemas,
  schemaTables,
  swiftSchemas,
} from './prop-schemas.ts';
import type {
  Alias,
  DocRow,
  Kind,
  Kinds,
  Manifest,
  Platform,
  PropSpec,
  Effect,
  Unset,
  ValueType,
} from './manifest.ts';

/** A generated file's contents, by path from the repository root. */
export type GeneratedFiles = Record<string, string>;

/** Reads a checked-in file whose generated regions are replaced. */
export type ReadFile = (path: string) => string;

const HEADER =
  'Generated by scripts/generate-protocol.ts from src/protocol/manifest.ts. Do not edit.';

export const PRIMITIVES_DOC = 'docs/primitives.md';

export const MODULES_DOC = 'docs/native-modules.md';

/** The kernel's tables, the app's prop types and the docs' prop tables. */
export function generateProtocol(manifest: Manifest, read: ReadFile): GeneratedFiles {
  validate(manifest);

  const layouts = eventLayouts(manifest);

  return {
    'native/shared/PropSchemas.generated.h': cppSchemas(HEADER, manifest, schemaTables(manifest)),
    'native/ios/Renderer/KuitoPropValues.generated.swift': swiftSchemas(HEADER, manifest),
    'native/android/app/src/main/java/dev/kuito/runtime/renderer/KuitoPropValues.generated.kt':
      kotlinSchemas(HEADER, manifest),
    'native/shared/EventLayouts.generated.h': cppLayouts(HEADER, layouts),
    'native/ios/Renderer/KuitoEvents.generated.swift': swiftLayouts(HEADER, manifest, layouts),
    'native/android/app/src/main/java/dev/kuito/runtime/renderer/KuitoEvents.generated.kt':
      kotlinLayouts(HEADER, manifest, layouts),
    'src/runtime/protocol.generated.ts': kernelTables(manifest),
    'src/ui/props.generated.d.ts': propTypes(manifest),
    [PRIMITIVES_DOC]: primitiveDocs(manifest, read(PRIMITIVES_DOC)),
    'native/shared/PropKeys.generated.h': propKeys(manifest),
    'native/ios/Renderer/KuitoProps.generated.swift': swiftProps(manifest),
    'native/android/app/src/main/java/dev/kuito/runtime/renderer/KuitoProps.generated.kt':
      kotlinProps(manifest),
    'native/ios/Modules/KuitoModuleProtocol.generated.swift': swiftModules(manifest.modules),
    'native/ios/App/KuitoDevLink.generated.swift': swiftDevLink(manifest.devLink),
    'native/android/app/src/main/java/dev/kuito/runtime/KuitoDevLink.generated.kt': kotlinDevLink(
      manifest.devLink,
    ),
    'native/android/app/src/main/java/dev/kuito/runtime/modules/KuitoModuleProtocol.generated.kt':
      kotlinModules(manifest.modules),
    [MODULES_DOC]: moduleDocs(manifest.modules, read(MODULES_DOC)),
  };
}

function fail(message: string): never {
  throw new Error('src/protocol/manifest.ts: ' + message);
}

function isKind(manifest: Manifest, name: string): name is Kind {
  return Object.hasOwn(manifest.kinds, name);
}

function kindNames(manifest: Manifest): Kind[] {
  return Object.keys(manifest.kinds).filter((name) => isKind(manifest, name));
}

/** The kinds a prop's `kinds` names. */
function kindsOf(manifest: Manifest, kinds: Kinds): Kind[] {
  if (kinds === 'all') return kindNames(manifest);

  if (kinds === 'containers')
    return kindNames(manifest).filter((kind) => manifest.kinds[kind].container);

  return [...kinds];
}

function aliasesOf(manifest: Manifest, spec: PropSpec): [Kind, Alias][] {
  return Object.entries(spec.aliases ?? {}).flatMap(([kind, alias]): [Kind, Alias][] =>
    alias && isKind(manifest, kind) ? [[kind, alias]] : [],
  );
}

/** The props an app writes on a kind: native names, aliases and events. */
function appProps(manifest: Manifest, kind: Kind): Set<string> {
  const names = new Set<string>(Object.keys(manifest.eventProps));

  for (const [name, spec] of Object.entries(manifest.props)) {
    if (spec.internal || !kindsOf(manifest, spec.kinds).includes(kind)) continue;

    const alias = spec.aliases?.[kind];

    if (spec.group) names.add(spec.group.name);
    else if (!alias?.only) names.add(name);

    if (alias) names.add(alias.name);
  }

  const variant = manifest.kinds[kind].variant;

  if (variant) names.add(variant.prop);

  return names;
}

function validate(manifest: Manifest): void {
  const kinds = kindNames(manifest);

  for (const [name, spec] of Object.entries(manifest.props)) {
    if (spec.type === 'enum' && !spec.values?.length) fail(`${name} is an enum without values`);
    if (spec.type !== 'enum' && spec.values) fail(`${name} lists values but is not an enum`);

    if (spec.type === 'json' && !spec.internal && !spec.ts)
      fail(`${name} is json without a ts type`);

    if (spec.type === 'json' && !spec.kernel && !spec.schema)
      fail(`${name} is json without a schema: C++ checks its value once against it`);

    if (spec.schema && (spec.type !== 'json' || spec.kernel))
      fail(`${name} has a schema, but only a json prop a renderer receives takes one`);

    if (Array.isArray(spec.kinds))
      for (const kind of spec.kinds) if (!kinds.includes(kind)) fail(`${name} names kind ${kind}`);

    if (typeof spec.unset === 'object') unsetValue(name, spec, spec.unset.value);

    for (const [kind, alias] of aliasesOf(manifest, spec)) {
      if (!kindsOf(manifest, spec.kinds).includes(kind))
        fail(`${name} has an alias on ${kind}, which it is not a prop of`);

      if (alias.only && !Array.isArray(spec.kinds))
        fail(`${name} replaces its name on ${kind} but every view takes it`);
    }

    if (Object.keys(spec.aliases ?? {}).length !== aliasesOf(manifest, spec).length)
      fail(`${name} has an alias on an unknown kind`);
  }

  // The app's ImageSource types and the src schema C++ checks describe the same objects.
  const src = manifest.props.src?.schema;
  const sourceShapes =
    src && typeof src === 'object' && 'oneOf' in src
      ? src.variants.flatMap(({ schema }) =>
          typeof schema === 'object' && 'struct' in schema
            ? [Object.keys(schema.fields).sort().join()]
            : [],
        )
      : [];

  for (const [name, fields] of Object.entries(manifest.imageSources))
    if (!sourceShapes.includes(Object.keys(fields).sort().join()))
      fail(`${name} has no variant with its fields in src's schema`);

  for (const [event, spec] of Object.entries(manifest.events))
    for (const [kind, payload] of Object.entries(spec)) {
      if (kind !== 'all' && !isKind(manifest, kind)) fail(`event ${event} names kind ${kind}`);

      if (payload !== null && !Object.hasOwn(manifest.payloads, payload))
        fail(`event ${event} names payload ${payload}, which has no layout in PAYLOADS`);
    }

  for (const [target, events] of Object.entries(manifest.systemEvents))
    for (const [event, payload] of Object.entries(events))
      if (payload !== null && !Object.hasOwn(manifest.payloads, payload))
        fail(`${target}.${event} names payload ${payload}, which has no layout in PAYLOADS`);

  for (const [prop, spec] of Object.entries(manifest.eventProps)) {
    const event = spec.event.replace(/:capture$/, '');

    if (!Object.hasOwn(manifest.events, event)) fail(`${prop} listens to unknown event ${event}`);

    for (const name of [spec.announce, ...Object.keys(spec.everyFrame ?? {})])
      if (name !== undefined && !Object.hasOwn(manifest.props, name))
        fail(`${prop} sets ${name}, which is not a native prop`);

    // A motion source's fields are motion values: numbers, which cross without JSON.
    if (spec.source)
      for (const payload of Object.values(manifest.events[event] ?? {}))
        if (
          payload === null ||
          Object.values(manifest.payloads[payload] ?? {}).some((type) => type !== 'number')
        )
          fail(`${prop} is a motion source, but ${payload ?? 'no payload'} is not all numbers`);
  }

  for (const kind of kinds) {
    const variant = manifest.kinds[kind].variant;

    if (variant && !kinds.includes(variant.kind))
      fail(`${kind}'s ${variant.prop} picks unknown kind ${variant.kind}`);

    const allowed = appProps(manifest, kind);

    for (const row of manifest.kinds[kind].docs ?? [])
      for (const name of row.props)
        if (!allowed.has(name)) fail(`the ${kind} docs list ${name}, which ${kind} does not take`);
  }
}

// --- src/runtime/protocol.generated.ts --------------------------------------

const quote = (text: string) => `'${text.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;

const key = (name: string) => (/^[A-Za-z_$][\w$]*$/.test(name) ? name : quote(name));

function stringList(names: readonly string[]): string {
  return '[\n' + names.map((name) => `  ${quote(name)},\n`).join('') + ']';
}

function frozenSet(names: readonly string[], indent = ''): string {
  const pad = indent + '  ';

  return (
    'Object.freeze({\n' +
    names.map((name) => `${pad}${key(name)}: true,\n`).join('') +
    indent +
    '})'
  );
}

function union(names: readonly (string | number)[]): string {
  return names.map((name) => (typeof name === 'number' ? String(name) : quote(name))).join(' | ');
}

function literal(value: unknown): string {
  if (typeof value === 'string') return quote(value);
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) return '[' + value.map(literal).join(', ') + ']';

  if (typeof value === 'object' && value !== null)
    return (
      '{ ' +
      Object.entries(value)
        .filter(([, field]) => field !== undefined)
        .map(([name, field]) => `${key(name)}: ${literal(field)}`)
        .join(', ') +
      ' }'
    );

  return fail(`cannot write ${String(value)} as TypeScript`);
}

const FIELD_TYPES = {
  number: 'number',
  'number?': 'number',
  string: 'string',
  boolean: 'boolean',
  'headers?': 'Readonly<Record<string, string>>',
} as const;

function payloadInterfaces(payloads: Manifest['imageSources']): string {
  return Object.entries(payloads)
    .map(
      ([name, fields]) =>
        `export interface ${name} {\n` +
        Object.entries(fields)
          .map(
            ([field, type]) =>
              `  ${key(field)}${type.endsWith('?') ? '?' : ''}: ${FIELD_TYPES[type]};\n`,
          )
          .join('') +
        '}\n',
    )
    .join('\n');
}

/** Layout props the engine applies without a native view (docs/flattening.md). */
function layoutProps(manifest: Manifest): string[] {
  return Object.entries(manifest.props)
    .filter(([, spec]) => spec.concern === 'layout' && !spec.needsView)
    .map(([name]) => name);
}

/** Each group field's native prop and the kinds that take it. */
function groupFieldKinds(manifest: Manifest): [string, Kind[]][] {
  return Object.entries(manifest.props).flatMap(([name, spec]) =>
    spec.group ? [[name, kindsOf(manifest, spec.kinds)] as [string, Kind[]]] : [],
  );
}

/** Each grouping object prop's fields and the native props they set. */
function propGroupTable(manifest: Manifest): [string, Record<string, string>][] {
  const groups = new Map<string, Record<string, string>>();

  for (const [name, spec] of Object.entries(manifest.props))
    if (spec.group)
      groups.set(spec.group.name, { ...groups.get(spec.group.name), [spec.group.field]: name });

  return [...groups];
}

/** Each kind's reported props by event, with the native prop that announces the event. */
function reportedProps(manifest: Manifest) {
  return kindNames(manifest).flatMap((kind) => {
    const events: Record<string, Record<string, unknown>> = {};

    for (const [prop, spec] of Object.entries(manifest.props)) {
      const report = spec.reports?.[kind];

      if (!report) continue;
      if (events[report.event]) fail(`${kind} reports two props with ${report.event}`);

      const announce = Object.values(manifest.eventProps).find(
        (eventProp) => eventProp.event === report.event && eventProp.announce,
      )?.announce;

      events[report.event] = { prop, ...report, ...(announce && { announce }) };
    }

    return Object.keys(events).length ? [[kind, events] as const] : [];
  });
}

function kernelTables(manifest: Manifest): string {
  const kinds = kindNames(manifest);
  const props = Object.keys(manifest.props);
  const variants = kinds.flatMap((kind) => {
    const variant = manifest.kinds[kind].variant;

    return variant ? [[kind, variant] as const] : [];
  });
  // A variant prop that is no native prop only picks the kind: neither kind is sent it.
  const structural = variants
    .filter(([, variant]) => !Object.hasOwn(manifest.props, variant.prop))
    .flatMap(([kind, variant]) => [
      [kind, variant.prop] as const,
      [variant.kind, variant.prop] as const,
    ]);
  const aliases = kinds.flatMap((kind) => {
    const names = Object.entries(manifest.props).flatMap(([name, spec]) => {
      const alias = spec.aliases?.[kind];

      return alias ? [[alias.name, name] as const] : [];
    });

    return names.length ? [[kind, Object.fromEntries(names)] as const] : [];
  });

  return `// ${HEADER}
import type { EventLayout } from './event-records';
import type { EventProp, ReportedProp } from './events';

/** A native prop's name. */
export type NativeProp =
${props.map((name) => `  | ${quote(name)}`).join('\n')};

/** The kinds of native view the renderers make. */
export const NATIVE_KINDS: readonly string[] = ${stringList(kinds)};

/** Kinds whose children are native views. */
export const CONTAINERS: readonly string[] = ${stringList(kinds.filter((kind) => manifest.kinds[kind].container))};

/** Kinds whose native view is a plain container: nothing but a frame. */
export const FLATTENABLE_KINDS: readonly string[] = ${stringList(kinds.filter((kind) => manifest.kinds[kind].flattenable))};

/** Kinds that take scroll requests: their elements have \`scrollTo\` and \`scrollToEnd\`. */
export const SCROLLING_KINDS: readonly string[] = ${stringList(kindsOf(manifest, manifest.props.scrollTo.kinds))};

/** Props sent after a view's others when they reach it together: a selection indexes into the text. */
export const LAST_PROPS: readonly string[] = ${stringList(props.filter((name) => manifest.props[name].last))};

/** Props every kind takes, a module's view among them; its other props are its module's own and cross by name. */
export const EVERY_KIND_PROPS: Readonly<Record<string, true>> = ${frozenSet(props.filter((name) => manifest.props[name].kinds === 'all'))};

/** Kinds whose native view is fixed when made: the prop that picks another kind while truthy, and that kind. */
export const KIND_VARIANTS: Readonly<Record<string, { prop: string; kind: string }>> = Object.freeze({
${variants.map(([kind, variant]) => `  ${key(kind)}: { prop: ${quote(variant.prop)}, kind: ${quote(variant.kind)} },\n`).join('')}});

/** Props that choose the native kind instead of being sent to it. */
export const STRUCTURAL_PROPS: Readonly<Record<string, readonly string[]>> = Object.freeze({
${structural.map(([kind, prop]) => `  ${key(kind)}: [${quote(prop)}],\n`).join('')}});

/** App prop names that map onto a native prop of another name, by kind. */
export const PROP_ALIASES: Readonly<Record<string, Readonly<Record<string, string>>>> =
  Object.freeze({
${aliases.map(([kind, names]) => `    ${key(kind)}: ${literal(names)},\n`).join('')}  });

/**
 * Props the layout engine applies without a view. Every other prop
 * (decoration, opacity, transforms, clipping, visibility, accessibility,
 * native ids, animation config) needs a view.
 */
export const LAYOUT_PROPS: Readonly<Record<string, true>> = ${frozenSet(layoutProps(manifest))};

/** Requests the view acts on when it receives one: never recorded as its props, so never unset. */
export const REQUEST_PROPS: Readonly<Record<string, true>> = ${frozenSet(
    Object.entries(manifest.props)
      .filter(([, spec]) => spec.request)
      .map(([name]) => name),
  )};

/** Props whose keys cross as edits to the keys sent before (docs/lists.md#keys). */
export const KEY_PROPS: Readonly<Record<string, true>> = ${frozenSet(
    Object.entries(manifest.props)
      .filter(([, spec]) => spec.type === 'keys')
      .map(([name]) => name),
  )};

/** Animatable props and the \`transition\` group that says how each one moves. */
export const ANIMATABLE_PROPS: Readonly<Record<string, string>> = Object.freeze({
${Object.entries(manifest.props)
  .flatMap(([name, spec]) =>
    spec.animatable ? [`  ${key(name)}: ${quote(spec.animatable)},\n`] : [],
  )
  .join('')}});

/**
 * Each native prop's key on the wire: its index in the manifest, as
 * native/shared/PropKeys.generated.h numbers it (docs/native-scheduling.md).
 */
export const PROP_KEYS: Readonly<Record<string, number>> = Object.freeze({
${props.map((name, index) => `  ${key(name)}: ${index},\n`).join('')}});

/**
 * The host's own module error codes (docs/native-modules.md#errors), by
 * name: the kernel's checks fail with the code the host would.
 */
export const ERROR_CODES = {
${Object.entries(manifest.modules.errors)
  .map(([name, spec]) => `  ${key(name)}: ${quote(spec.code)},\n`)
  .join('')}} as const;

/** Object props that group options, by name: each field and the native prop it sets. */
export const PROP_GROUPS: Readonly<Record<string, Readonly<Record<string, string>>>> =
  Object.freeze({
${propGroupTable(manifest)
  .map(([name, fields]) => `    ${key(name)}: ${literal(fields)},\n`)
  .join('')}  });

/**
 * Kinds that take each field of an object prop. A compiled object is a
 * function, so every field is planned and a dropped one is cleared. A field
 * the kind lacks is not sent, not even as a clear.
 */
export const GROUP_FIELD_KINDS: Readonly<Record<string, Readonly<Record<string, true>>>> =
  Object.freeze({
${groupFieldKinds(manifest)
  .map(([name, kinds]) => `  ${key(name)}: ${frozenSet(kinds, '  ')},\n`)
  .join('')}});

/**
 * Props a view changes itself and reports, by kind and event: the payload
 * field with the new value, or the value the event means. A prop bound to a
 * writable signal writes it; \`announce\` turns the event on (docs/events.md).
 */
export const REPORTED_PROPS: Readonly<Record<string, Readonly<Record<string, ReportedProp>>>> =
  Object.freeze({
${reportedProps(manifest)
  .map(([kind, events]) => `    ${key(kind)}: ${literal(events)},\n`)
  .join('')}  });

/** React Native event props and the native event each one listens to. */
export const EVENT_PROPS: Readonly<Record<string, EventProp>> = Object.freeze({
${Object.entries(manifest.eventProps)
  .map(([name, spec]) => `  ${key(name)}: ${literal(spec)},\n`)
  .join('')}});

${kernelLayouts(manifest, eventLayouts(manifest))}
${payloadInterfaces(manifest.payloads)}`;
}

// --- src/ui/props.generated.d.ts --------------------------------------------

/** Where the types a prop's `ts` names come from. */
const TS_IMPORTS: Readonly<Record<string, readonly string[]>> = {
  './animations': ['AnimatedProps', 'Animation', 'Effect', 'Transition'],
  './primitives': [
    'AccessibilityAction',
    'Animatable',
    'Bound',
    'ContentAlignment',
    'LengthPercentage',
    'LengthPercentageAuto',
    'Prop',
    'SafeAreaEdge',
    'SelfAlignment',
    'SizeValue',
    'SnapPoint',
    'SymbolName',
  ],
};

const BUILT_IN_TYPES = ['Partial', 'Readonly', 'Record'];

const SCALAR_TYPES: Readonly<Record<Exclude<ValueType, 'enum' | 'json'>, string>> = {
  number: 'number',
  boolean: 'boolean',
  string: 'string',
  color: 'string',
  length: 'LengthPercentage',
  lengthAuto: 'LengthPercentageAuto',
  size: 'SizeValue',
  keys: 'readonly string[]',
};

/** The value's own type, without the signal or animation a prop also takes. */
function valueType(spec: PropSpec): string {
  if (spec.type === 'json') return spec.ts ?? fail('a json prop needs a ts type');

  return (
    spec.typeName?.name ??
    spec.ts ??
    (spec.type === 'enum' ? union(spec.values ?? []) : SCALAR_TYPES[spec.type])
  );
}

function propType(spec: PropSpec): string {
  const base = valueType(spec);

  if (spec.type === 'json' && !spec.reports) return spec.reactive ? `Prop<${base}>` : base;

  if (spec.animatable) return `Animatable<${base}>`;

  return spec.reports ? `Bound<${base}>` : `Prop<${base}>`;
}

function comment(doc: string | undefined, indent: string): string {
  return doc ? `${indent}/** ${doc} */\n` : '';
}

function member(name: string, type: string, optional: boolean, doc?: string): string {
  return `${comment(doc, '  ')}  ${key(name)}${optional ? '?' : ''}: ${type};\n`;
}

interface PropGroup {
  name: string;
  doc: string;
  members: string[];
}

/**
 * The object props that group options (`keyboard={{ dismiss }}`), with the
 * fields `takes` admits, as members.
 */
function groupMembers(manifest: Manifest, takes: (spec: PropSpec) => boolean): string[] {
  const groups = new Map<string, string[]>();

  for (const spec of Object.values(manifest.props)) {
    if (!spec.group || spec.internal || !takes(spec)) continue;

    const fields = groups.get(spec.group.name) ?? [];

    fields.push(`${comment(spec.doc, '    ')}    ${key(spec.group.field)}?: ${valueType(spec)};\n`);
    groups.set(spec.group.name, fields);
  }

  return [...groups].map(([name, fields]) => member(name, `Prop<{\n${fields.join('')}  }>`, true));
}

function propGroups(manifest: Manifest): PropGroup[] {
  const entries = Object.entries(manifest.props).filter(
    ([, spec]) => !spec.internal && !spec.group,
  );
  const shared = (kinds: Kinds, test: (spec: PropSpec) => boolean) => [
    ...entries
      .filter(([, spec]) => spec.kinds === kinds && test(spec))
      .map(([name, spec]) => member(name, propType(spec), !spec.required, spec.doc)),
    ...groupMembers(manifest, (spec) => spec.kinds === kinds && test(spec)),
  ];
  const groups: PropGroup[] = [
    {
      name: 'LayoutProps',
      doc: "CSS flexbox and positioning, laid out by a port of Taffy's algorithm on both platforms (see docs/styles.md#layout).",
      members: shared('all', (spec) => spec.concern === 'layout'),
    },
    {
      name: 'AccessibilityNativeProps',
      doc: 'The native accessibility props every view takes (docs/accessibility.md).',
      members: shared('all', (spec) => spec.concern === 'accessibility'),
    },
    {
      name: 'CommonNativeProps',
      doc: 'The other native props every view takes.',
      members: shared(
        'all',
        (spec) => spec.concern !== 'layout' && spec.concern !== 'accessibility',
      ),
    },
    {
      name: 'ContainerNativeProps',
      doc: 'The native props every container takes.',
      members: shared('containers', () => true),
    },
  ];

  for (const kind of kindNames(manifest)) {
    if (!manifest.kinds[kind].primitive) continue;

    // A kind's own grouped fields, with the containers' it shares, override
    // the shared group's member of that name.
    const own = (spec: PropSpec) => Array.isArray(spec.kinds) && spec.kinds.includes(kind);
    const grouped = Object.values(manifest.props).some((spec) => spec.group && own(spec))
      ? groupMembers(
          manifest,
          (spec) => own(spec) || (spec.kinds === 'containers' && manifest.kinds[kind].container),
        )
      : [];
    const members = entries.flatMap(([name, spec]) => {
      if (!Array.isArray(spec.kinds) || !spec.kinds.includes(kind)) {
        const alias = spec.aliases?.[kind];

        return alias
          ? [member(alias.name, alias.ts ?? propType(spec), true, alias.doc ?? spec.doc)]
          : [];
      }

      const alias = spec.aliases?.[kind];
      const own = alias?.only ? [] : [member(name, propType(spec), !spec.required, spec.doc)];

      return alias
        ? [
            ...own,
            member(alias.name, alias.ts ?? propType(spec), !spec.required, alias.doc ?? spec.doc),
          ]
        : own;
    });

    members.push(...grouped);

    if (members.length)
      groups.push({ name: `${kind}NativeProps`, doc: `The native props ${kind} takes.`, members });
  }

  return groups;
}

function imports(text: string): string {
  const used = new Set(text.match(/\b[A-Z]\w*\b/g) ?? []);
  const lines = Object.entries(TS_IMPORTS).flatMap(([module, names]) => {
    const needed = names.filter((name) => used.has(name));

    return needed.length ? [`import type { ${needed.join(', ')} } from '${module}';\n`] : [];
  });

  return lines.join('');
}

function propTypes(manifest: Manifest): string {
  const named = Object.values(manifest.props).flatMap((spec) =>
    spec.typeName
      ? [
          `${comment(spec.typeName.doc, '')}export type ${spec.typeName.name} =\n${(spec.values ?? []).map((value) => `  | ${union([value])}`).join('\n')};\n`,
        ]
      : [],
  );
  const groups = propGroups(manifest).map(
    (group) =>
      `${comment(group.doc, '')}export interface ${group.name} {\n${group.members.join('')}}\n`,
  );
  const sources = Object.keys(manifest.imageSources);
  const elementProperties = Object.entries(manifest.props)
    .filter(([, spec]) => !spec.internal)
    .map(([name, spec]) => `  ${key(name)}: ${valueType(spec)};\n`)
    .join('');
  const body = [
    ...named,
    ...groups,
    `/** Each native prop an element's \`setProperty\` sets, and its value; null resets it. */\nexport interface ElementProperties {\n${elementProperties}}\n`,
    payloadInterfaces(manifest.payloads),
    payloadInterfaces(manifest.imageSources),
    `/** What an Image shows: a URL string, or one of the objects \`src\` takes. */\nexport type ImageSource = string | ${sources.join(' | ')};\n`,
  ].join('\n');
  const known = new Set([
    ...Object.values(TS_IMPORTS).flat(),
    ...BUILT_IN_TYPES,
    ...Object.values(manifest.props).flatMap((spec) => (spec.typeName ? [spec.typeName.name] : [])),
    ...propGroups(manifest).map((group) => group.name),
    'ElementProperties',
    ...Object.keys(manifest.payloads),
    ...sources,
    'ImageSource',
  ]);

  for (const name of body.replace(/\/\*\*.*?\*\//g, '').match(/\b[A-Z]\w*\b/g) ?? [])
    if (!known.has(name))
      fail(`a ts type names ${name}, which generate.ts does not know where to import from`);

  return `// ${HEADER}\n${imports(body)}\n${body}`;
}

// --- docs/primitives.md -----------------------------------------------------

const DOC_START = (kind: string) =>
  `<!-- ${kind} props: generated from src/protocol/manifest.ts -->`;
const DOC_END = '<!-- end of generated props -->';

/** A Markdown table padded the way the formatter pads it. */
export function markdownTable(rows: readonly (readonly string[])[]): string {
  const widths = rows[0].map((_, column) => Math.max(3, ...rows.map((row) => row[column].length)));
  const line = (cells: readonly string[]) =>
    '| ' + cells.map((cell, column) => cell.padEnd(widths[column])).join(' | ') + ' |';

  return [
    line(rows[0]),
    line(widths.map((width) => '-'.repeat(width))),
    ...rows.slice(1).map(line),
  ].join('\n');
}

function docRow(row: DocRow): string[] {
  const names = row.props.map((name) => '`' + name + '`').join(row.join ?? ' / ');

  return [names + (row.kuito ? ' _(Kuito)_' : ''), row.text];
}

function primitiveDocs(manifest: Manifest, text: string): string {
  let result = text;

  for (const kind of kindNames(manifest)) {
    const rows = manifest.kinds[kind].docs;

    if (!rows) continue;

    const start = result.indexOf(DOC_START(kind));
    const end = result.indexOf(DOC_END, start);

    if (start === -1 || end === -1)
      fail(`${PRIMITIVES_DOC} has no generated props region for ${kind}`);

    result =
      result.slice(0, start) +
      DOC_START(kind) +
      '\n\n' +
      markdownTable([['Prop', 'Meaning'], ...rows.map(docRow)]) +
      '\n\n' +
      result.slice(end);
  }

  return result;
}

// --- Native ---------------------------------------------------------------

const VALUE_KINDS: Readonly<Record<ValueType, string>> = {
  number: 'Number',
  boolean: 'Boolean',
  string: 'String',
  color: 'Color',
  enum: 'Enum',
  length: 'Length',
  lengthAuto: 'LengthAuto',
  size: 'Size',
  json: 'Json',
  keys: 'Keys',
};

const EFFECT_NAMES: Record<Effect, string> = {
  paint: 'Paint',
  measure: 'Measure',
  layout: 'Layout',
  structure: 'Structure',
};

const effectName = (effect: Effect) => EFFECT_NAMES[effect];

/** `aria-valuemin` → `AriaValuemin`. */
const pascal = (name: string) =>
  name.replace(/(^|-)([a-z])/g, (_, _dash: string, letter: string) => letter.toUpperCase());

function propKeys(manifest: Manifest): string {
  const props = Object.entries(manifest.props);
  const values = props.flatMap(([name, spec]) =>
    spec.values ? [[name, spec.values.map(String)] as const] : [],
  );
  const hasValues = (name: string) => values.some(([prop]) => prop === name);
  // One value a line, its index in a comment: the layout clang-format keeps.
  const valueArray = (name: string, list: readonly string[]) => {
    const lines = list.map((value) => `    "${value}",`);
    const width = Math.max(...lines.map((line) => line.length));

    return (
      `inline constexpr std::array<std::string_view, ${list.length}> k${pascal(name)}Values{\n` +
      lines.map((line, index) => `${line.padEnd(width)} // ${index}\n`).join('') +
      '};\n'
    );
  };

  return `// ${HEADER}
// Every native prop, interned: a PropKey is its index in kProps.
#pragma once

#include <array>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <string_view>

namespace kuito {

// How a prop's value crosses the host boundary (ValueType in the manifest).
enum class ValueKind : std::uint8_t { ${Object.values(VALUE_KINDS).join(', ')} };

// What a write of the prop can disturb (Effect in the manifest).
enum class PropEffect : std::uint8_t { Paint, Measure, Layout, Structure };

enum class PropKey : std::uint16_t {
${props.map(([name]) => `  ${pascal(name)},\n`).join('')}};

// An enum prop's values: its enumValue is an index into them.
${values.map(([name, list]) => valueArray(name, list)).join('\n')}
struct PropInfo {
  std::string_view name;
  ValueKind kind;
  PropEffect effect;
  const std::string_view* values = nullptr;
  std::size_t valueCount = 0;

  constexpr PropInfo(std::string_view name, ValueKind kind, PropEffect effect)
      : name(name), kind(kind), effect(effect) {}
  template <std::size_t N>
  constexpr PropInfo(std::string_view name, ValueKind kind, PropEffect effect,
                     const std::array<std::string_view, N>& values)
      : name(name), kind(kind), effect(effect), values(values.data()), valueCount(N) {}
};

inline constexpr std::array<PropInfo, ${props.length}> kProps{{
${props.map(([name, spec]) => `    {"${name}", ValueKind::${VALUE_KINDS[spec.type]}, PropEffect::${effectName(spec.effect)}${hasValues(name) ? `, k${pascal(name)}Values` : ''}},\n`).join('')}}};

inline constexpr std::size_t kPropCount = kProps.size();

inline constexpr const PropInfo& propInfo(PropKey key) { return kProps[static_cast<std::size_t>(key)]; }

inline constexpr std::optional<PropKey> propKey(std::string_view name) {
  for (std::size_t index = 0; index < kProps.size(); ++index)
    if (kProps[index].name == name) return static_cast<PropKey>(index);
  return std::nullopt;
}

/// The index of \`value\` among an enum prop's values.
inline constexpr std::optional<std::int32_t> enumValue(PropKey key, std::string_view value) {
  const PropInfo& info = propInfo(key);
  for (std::size_t index = 0; index < info.valueCount; ++index)
    if (info.values[index] == value) return static_cast<std::int32_t>(index);
  return std::nullopt;
}

} // namespace kuito
`;
}

function platformProps(manifest: Manifest, platform: Platform): string[] {
  return Object.entries(manifest.props)
    .filter(([, spec]) => !spec.kernel && (!spec.platforms || spec.platforms.includes(platform)))
    .map(([name]) => name);
}

/** An enum prop's values as a Swift or Kotlin list's items; none for another prop. */
function enumValues(spec: PropSpec, language: 'swift' | 'kotlin'): string {
  return spec.type === 'enum' && spec.values
    ? spec.values.map((value) => nativeString(String(value), language)).join(', ')
    : '';
}

function swiftProps(manifest: Manifest): string {
  return `// ${HEADER}

/// The native props src/protocol/manifest.ts marks for iOS: KuitoProperties
/// has a setter for each (native/ios/Tests, test/protocol-parity.test.ts).
enum KuitoProps {
    static let names: Set<String> = [
${platformProps(manifest, 'ios')
  .map((name) => `        "${name}",\n`)
  .join('')}    ]

    /// Every prop's name by its key on the wire (native/shared/PropKeys.generated.h).
    static let byKey: [String] = [
${Object.keys(manifest.props)
  .map((name) => `        "${name}",\n`)
  .join('')}    ]

    /// What null means for each prop, by its key (docs/native-renderer.md#unset-props).
    static let unsetByKey: [KuitoUnset] = [
${Object.entries(manifest.props)
  .map(([name, spec]) => `        ${swiftUnset(name, spec)}, // ${name}\n`)
  .join('')}    ]

    /// An enum prop's values by its key, which a record's index reads: an
    /// enum crosses the batch as its index alone. Empty for other props.
    static let valuesByKey: [[String]] = [
${Object.entries(manifest.props)
  .map(([name, spec]) => `        [${enumValues(spec, 'swift')}], // ${name}\n`)
  .join('')}    ]

    /// What a write of each prop can disturb, by its key (Effect in the manifest).
    static let effectByKey: [KuitoPropEffect] = [
${Object.entries(manifest.props)
  .map(([name, spec]) => `        .${spec.effect}, // ${name}\n`)
  .join('')}    ]
}

/// What a write of a prop can disturb (\`Effect\` in src/protocol/manifest.ts).
enum KuitoPropEffect {
    case paint, measure, layout, structure
}

/// What null means for a prop: a value it stands for, the view's own initial
/// state, or an error (\`Unset\` in src/protocol/manifest.ts).
enum KuitoUnset: Equatable {
    case value(KuitoValue)
    case initial
    case required
}
`;
}

function kotlinProps(manifest: Manifest): string {
  return `// ${HEADER}
package dev.kuito.runtime.renderer

/**
 * The native props src/protocol/manifest.ts marks for Android: KuitoProperties
 * has a setter for each (androidTest, test/protocol-parity.test.ts).
 */
internal object KuitoProps {
    val names: Set<String> = setOf(
${platformProps(manifest, 'android')
  .map((name) => `        "${name}",\n`)
  .join('')}    )

    /** Every prop's name by its key on the wire (native/shared/PropKeys.generated.h). */
    val byKey: Array<String> = arrayOf(
${Object.keys(manifest.props)
  .map((name) => `        "${name}",\n`)
  .join('')}    )

    /** What null means for each prop, by its key (docs/native-renderer.md#unset-props). */
    val unsetByKey: Array<KuitoUnset> = arrayOf(
${Object.entries(manifest.props)
  .map(([name, spec]) => `        ${kotlinUnset(name, spec)}, // ${name}\n`)
  .join('')}    )

    /**
     * An enum prop's values by its key, which a record's index reads: an
     * enum crosses the batch as its index alone. Empty for other props.
     */
    val valuesByKey: Array<Array<String>> = arrayOf(
${Object.entries(manifest.props)
  .map(([name, spec]) => `        arrayOf(${enumValues(spec, 'kotlin')}), // ${name}\n`)
  .join('')}    )

    /** What a write of each prop can disturb, by its key (Effect in the manifest). */
    val effectByKey: Array<KuitoPropEffect> = arrayOf(
${Object.entries(manifest.props)
  .map(([name, spec]) => `        KuitoPropEffect.${effectName(spec.effect)}, // ${name}\n`)
  .join('')}    )
}

/** What a write of a prop can disturb (\`Effect\` in src/protocol/manifest.ts). */
internal enum class KuitoPropEffect { Paint, Measure, Layout, Structure }

/**
 * What null means for a prop: a value it stands for, the view's own initial
 * state, or an error (\`Unset\` in src/protocol/manifest.ts).
 */
internal sealed interface KuitoUnset {
    data class Value(val value: KuitoValue) : KuitoUnset
    data object Initial : KuitoUnset
    data object Required : KuitoUnset
}
`;
}

/** An unset rule's value as the renderers' typed value: a scalar, an enum's index and text, or JSON. */
type UnsetValue =
  | { type: 'number'; value: number }
  | { type: 'boolean'; value: boolean }
  | { type: 'string'; value: string }
  | { type: 'enum'; index: number; text: string }
  | { type: 'struct'; numbers: number[]; strings: string[] }
  | { type: 'color'; rgba: number };

function unsetValue(name: string, spec: PropSpec, value: unknown): UnsetValue {
  const mismatch = () => fail(`${name} unsets to ${JSON.stringify(value)}, not a ${spec.type}`);

  switch (spec.type) {
    case 'number':
      return typeof value === 'number' ? { type: 'number', value } : mismatch();
    case 'boolean':
      return typeof value === 'boolean' ? { type: 'boolean', value } : mismatch();
    case 'string':
      return typeof value === 'string' ? { type: 'string', value } : mismatch();
    case 'enum': {
      const index = (spec.values ?? []).findIndex((option) => String(option) === value);

      return index === -1 ? mismatch() : { type: 'enum', index, text: String(value) };
    }
    case 'json': {
      if (!spec.schema) return fail(`${name} unsets to a value but has no schema`);

      const record = flattenValue(spec.schema, value);

      return { type: 'struct', numbers: record.numbers, strings: record.strings };
    }
    case 'color':
      return typeof value === 'string' && /^#[0-9a-f]{6}$/i.test(value)
        ? { type: 'color', rgba: (parseInt(value.slice(1), 16) * 256 + 255) >>> 0 }
        : mismatch();
    case 'length':
    case 'lengthAuto':
    case 'size':
    case 'keys':
      return fail(`${name} is a ${spec.type}: unset, it is initial or required`);
  }
}

/** A string literal both Swift and Kotlin read the same; `$` is escaped for Kotlin. */
function nativeString(text: string, language: 'swift' | 'kotlin'): string {
  const escaped = JSON.stringify(text);

  return language === 'kotlin' ? escaped.replace(/\$/g, '\\$') : escaped;
}

const SWIFT_UNSET: Record<Exclude<Unset, object>, string> = {
  initial: '.initial',
  required: '.required',
};

function swiftUnset(name: string, spec: PropSpec): string {
  if (typeof spec.unset !== 'object') return SWIFT_UNSET[spec.unset];

  const value = unsetValue(name, spec, spec.unset.value);

  switch (value.type) {
    case 'number':
      return `.value(.number(${value.value}))`;
    case 'boolean':
      return `.value(.bool(${value.value}))`;
    case 'string':
      return `.value(.text(${nativeString(value.value, 'swift')}))`;
    case 'enum':
      return `.value(.enumValue(${value.index}, ${nativeString(value.text, 'swift')}))`;
    case 'struct':
      return `.value(.structure(KuitoStructRecord(numbers: [${value.numbers.join(', ')}], strings: [${value.strings.map((text) => nativeString(text, 'swift')).join(', ')}])))`;
    case 'color':
      return `.value(.color(0x${value.rgba.toString(16).padStart(8, '0')}))`;
  }
}

const KOTLIN_UNSET: Record<Exclude<Unset, object>, string> = {
  initial: 'KuitoUnset.Initial',
  required: 'KuitoUnset.Required',
};

function kotlinUnset(name: string, spec: PropSpec): string {
  if (typeof spec.unset !== 'object') return KOTLIN_UNSET[spec.unset];

  const value = unsetValue(name, spec, spec.unset.value);
  const typed = (() => {
    switch (value.type) {
      case 'number':
        return `KuitoValue.Number(${Number.isInteger(value.value) ? value.value.toFixed(1) : value.value})`;
      case 'boolean':
        return `KuitoValue.Bool(${value.value})`;
      case 'string':
        return `KuitoValue.Text(${nativeString(value.value, 'kotlin')})`;
      case 'enum':
        return `KuitoValue.Enum(${value.index}, ${nativeString(value.text, 'kotlin')})`;
      case 'struct':
        return `KuitoValue.Struct(KuitoStructRecord(listOf(${value.numbers.map((number) => number.toFixed(1)).join(', ')}), listOf(${value.strings.map((text) => nativeString(text, 'kotlin')).join(', ')})))`;
      case 'color':
        return `KuitoValue.Color(0x${value.rgba.toString(16).padStart(8, '0')}.toInt())`;
    }
  })();

  return `KuitoUnset.Value(${typed})`;
}

// --- Native modules --------------------------------------------------------

/** `ERR_MODULE_NOT_FOUND` → `MODULE_NOT_FOUND`. */
const constant = (code: string) => code.replace(/^ERR_/, '');

function errorsFor(modules: ModuleProtocol, platform: Platform): [string, ErrorSpec][] {
  return Object.entries(modules.errors).filter(
    ([, spec]) => !spec.platforms || spec.platforms.includes(platform),
  );
}

function swiftModules(modules: ModuleProtocol): string {
  const threads = Object.keys(modules.threads);

  return `// ${HEADER}
import Foundation

/// Where a function runs: \`js\` returns synchronously.
enum KuitoThread: String {
    case ${threads.join(', ')}
}

/// The host's own error codes (docs/native-modules.md#errors).
enum KuitoErrorCode {
${errorsFor(modules, 'ios')
  .map(([name, spec]) => `    /// ${spec.meaning}\n    static let ${name} = "${spec.code}"\n`)
  .join('')}}
`;
}

function kotlinModules(modules: ModuleProtocol): string {
  return `// ${HEADER}
package dev.kuito.runtime.modules

/** Where a function runs: \`js\` returns synchronously. */
enum class KuitoThread(val wire: String) {
${Object.keys(modules.threads)
  .map((thread) => `    ${thread.toUpperCase()}("${thread}"),\n`)
  .join('')}}

/** The host's own error codes (docs/native-modules.md#errors). */
object KuitoErrorCode {
${errorsFor(modules, 'android')
  .map(
    ([, spec]) =>
      `    /** ${spec.meaning} */\n    const val ${constant(spec.code)} = "${spec.code}"\n`,
  )
  .join('')}}
`;
}

// --- KuitoDevLink.generated.{swift,kt} -----------------------------------

const DEV_LINK_HEADER =
  'Generated by scripts/generate-protocol.ts from src/protocol/dev-link.ts. Do not edit.';

function swiftDevLink(link: DevLinkProtocol): string {
  const docs = (messages: Record<string, { doc: string }>) =>
    Object.entries(messages)
      .map(([type, { doc }]) => `/// - \`${type}\`: ${doc}`)
      .join('\n');

  return `// ${DEV_LINK_HEADER}
import Foundation

/// What the dev server sends a shell over the Live Patch link, by \`type\`.
${docs(link.server)}
enum KuitoServerMessage: String {
    case ${Object.keys(link.server).join(', ')}
}

/// What a shell sends the dev server over the Live Patch link, by \`type\`.
${docs(link.device)}
enum KuitoDeviceMessage: String {
    case ${Object.keys(link.device).join(', ')}
}

/// The codes a \`rejected\` message carries.
enum KuitoPatchRejection {
${Object.entries(link.rejections)
  .map(([name, { code, meaning }]) => `    /// ${meaning}\n    static let ${name} = "${code}"\n`)
  .join('')}}
`;
}

function kotlinDevLink(link: DevLinkProtocol): string {
  const constant = (name: string) => name.replace(/[A-Z]/g, (letter) => '_' + letter).toUpperCase();
  const enumeration = (name: string, what: string, messages: Record<string, { doc: string }>) =>
    `/**
 * ${what} over the Live Patch link, by \`type\`.
${Object.entries(messages)
  .map(([type, { doc }]) => ` * - \`${type}\`: ${doc}`)
  .join('\n')}
 */
enum class ${name}(val type: String) {
${Object.keys(messages)
  .map((type) => `    ${constant(type)}("${type}")`)
  .join(',\n')};

    companion object {
        fun of(type: String): ${name}? = entries.firstOrNull { it.type == type }
    }
}`;

  return `// ${DEV_LINK_HEADER}
package dev.kuito.runtime

${enumeration('KuitoServerMessage', 'What the dev server sends a shell', link.server)}

${enumeration('KuitoDeviceMessage', 'What a shell sends the dev server', link.device)}

/** The codes a \`rejected\` message carries. */
object KuitoPatchRejection {
${Object.entries(link.rejections)
  .map(
    ([name, { code, meaning }]) =>
      `    /** ${meaning} */\n    const val ${constant(name)} = "${code}"\n`,
  )
  .join('')}}
`;
}

const ERRORS_START = '<!-- error codes: generated from src/protocol/modules.ts -->';
const ERRORS_END = '<!-- end of generated error codes -->';

function moduleDocs(modules: ModuleProtocol, text: string): string {
  const start = text.indexOf(ERRORS_START);
  const end = text.indexOf(ERRORS_END, start);

  if (start === -1 || end === -1) fail(`${MODULES_DOC} has no generated error codes region`);

  const rows = Object.values(modules.errors).map((spec) => [
    '`' + spec.code + '`',
    spec.meaning +
      (spec.platforms
        ? ` ${spec.platforms.map((name) => (name === 'ios' ? 'iOS' : 'Android')).join(' and ')} only.`
        : ''),
  ]);

  return (
    text.slice(0, start) +
    ERRORS_START +
    '\n\n' +
    markdownTable([['Code', 'Meaning'], ...rows]) +
    '\n\n' +
    text.slice(end)
  );
}
